    `DECLARE`,
    `  batch_size CONSTANT int := 10000;`,
    `  touched int;`,
    `BEGIN`,
    `  LOOP`,
    `    UPDATE ${table} SET ${assignment}`,
    `    WHERE ctid IN (`,
    `      SELECT ctid FROM ${table}`,
    `      WHERE ${predicate}`,
    `      LIMIT batch_size`,
    `      FOR UPDATE SKIP LOCKED`,
    `    );`,
    `    GET DIAGNOSTICS touched = ROW_COUNT;`,
    `    EXIT WHEN touched = 0;`,
    `    COMMIT;`,
    `    PERFORM pg_sleep(0.1);`,
    `  END LOOP;`,
    `END $$;`
